import React, { useState, useRef } from "react";
import "./account.css";
import NavBar from "../Components/NavBar";
import Footer from "../Components/Footer";
import {
  createUserWithEmailAndPassword,
  signInWithEmailAndPassword,
} from "firebase/auth";
import { auth } from "../firebase";
import { useNavigate } from "react-router-dom";

export default function Account() {
  const [signUpData, setSignUpData] = useState({
    username: "",
    email: "",
    whatsapp: "", // ✅ WhatsApp field
    password: "",
    confirmPassword: "",
  });

  const [signInData, setSignInData] = useState({
    email: "",
    password: "",
  });

  const [error, setError] = useState("");
  const checkboxRef = useRef(null);
  const navigate = useNavigate();

  const handleSignUpChange = (e) => {
    setSignUpData({ ...signUpData, [e.target.name]: e.target.value });
  };

  const handleSignInChange = (e) => {
    setSignInData({ ...signInData, [e.target.name]: e.target.value });
  };

  const handleSignUp = async (e) => {
    e.preventDefault();
    setError("");

    if (signUpData.password !== signUpData.confirmPassword) {
      setError("Passwords do not match.");
      return;
    }

    try {
      const userCredential = await createUserWithEmailAndPassword(
        auth,
        signUpData.email,
        signUpData.password
      );

      // ✅ Save user details (username + WhatsApp) to backend
      await fetch("http://localhost:5000/users", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          uid: userCredential.user.uid,
          email: signUpData.email,
          username: signUpData.username,
          whatsapp: signUpData.whatsapp, // ✅ send WhatsApp to backend
          createdAt: new Date().toISOString(),
        }),
      });

      alert("Account created successfully!");
      if (checkboxRef.current) {
        checkboxRef.current.checked = true; // Switch to SignIn form
      }

      setSignUpData({
        username: "",
        email: "",
        whatsapp: "",
        password: "",
        confirmPassword: "",
      });
    } catch (err) {
      setError(err.message);
    }
  };

  const handleSignIn = async (e) => {
    e.preventDefault();
    setError("");

    try {
      const userCredential = await signInWithEmailAndPassword(
        auth,
        signInData.email,
        signInData.password
      );

      alert("Logged in successfully!");

      // ✅ Navigate to admin if admin email
      if (userCredential.user.email === "yasasmigunasinghe@gmail.com") {
        navigate("/admin");
      } else {
        navigate("/account");
      }
    } catch (err) {
      setError(err.message);
    }
  };

  return (
    <>
      <NavBar />
      <div className="acc-page">
        <section className="account">
          <input
            type="checkbox"
            id="check"
            aria-hidden="true"
            ref={checkboxRef}
          />

          {/* ✅ SIGNUP FORM */}
          <div className="signUp">
            <form onSubmit={handleSignUp}>
              <label htmlFor="check" aria-hidden="true" className="signup">
                Sign Up
              </label>
              <input
                type="text"
                name="username"
                placeholder="User Name"
                required
                value={signUpData.username}
                onChange={handleSignUpChange}
              />
              <input
                type="email"
                name="email"
                placeholder="Email"
                required
                value={signUpData.email}
                onChange={handleSignUpChange}
              />
              {/* ✅ WhatsApp input */}
              <input
                type="text"
                name="whatsapp"
                placeholder="WhatsApp Number"
                required
                value={signUpData.whatsapp}
                onChange={handleSignUpChange}
              />
              <input
                type="password"
                name="password"
                placeholder="Password"
                required
                value={signUpData.password}
                onChange={handleSignUpChange}
              />
              <input
                type="password"
                name="confirmPassword"
                placeholder="Confirm Password"
                required
                value={signUpData.confirmPassword}
                onChange={handleSignUpChange}
              />
              <button type="submit">Sign Up</button>
              {error && (
                <p style={{ color: "yellow", textAlign: "center" }}>{error}</p>
              )}
            </form>
          </div>

          {/* ✅ SIGNIN FORM */}
          <div className="signIn">
            <form onSubmit={handleSignIn}>
              <label htmlFor="check" aria-hidden="true">
                Sign In
              </label>
              <input
                type="email"
                name="email"
                placeholder="Email"
                required
                value={signInData.email}
                onChange={handleSignInChange}
              />
              <input
                type="password"
                name="password"
                placeholder="Password"
                required
                value={signInData.password}
                onChange={handleSignInChange}
              />
              <button type="submit">Sign In</button>
              <p>
                <a href="#">Forgot account?</a>
              </p>
              {error && (
                <p style={{ color: "yellow", textAlign: "center" }}>{error}</p>
              )}
            </form>
          </div>
        </section>
      </div>
      <Footer />
    </>
  );
}
